import React from 'react';
import { Link } from 'react-router-dom';
import '../styles/Blog.css';
import { postsData } from '../posts'; // Importamos los datos centralizados


const Blog = () => {
  return (
    <div className="blog-container">
      <Link to="/" className="pagina-btn-volver blog-volver-arriba">← Volver al Inicio</Link>
      <h1 className="blog-main-title">Nuestro Blog</h1>
      <p className="blog-intro">
        Mantente informado con las últimas noticias, consejos y análisis del mundo contable y financiero.
      </p>
      <div className="blog-posts-grid">
        {postsData.map(post => (
          <div key={post.id} className="blog-post-card">
            <div className="blog-video-container">
              <iframe
                className="blog-post-video"
                src={post.videoUrl}
                title={post.title}
                frameBorder="0"
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                allowFullScreen
              ></iframe>
            </div>
            <div className="blog-post-content">
              <p className="blog-post-date">{post.displayDate}</p>
              <h2 className="blog-post-title">{post.title}</h2>
              <p className="blog-post-excerpt">{post.summary}</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Blog;
